"""

    :param sent:
    :param word2id:
    :return:
    """
def sentence2id(sent: Any, word2id: Any) -> object {
    sentence_id = [];
    for word in sent {
        if word.isdigit() {
            word = '<NUM>';
        }
        if (word not in word2id) {
            word = '<UNK>';
        }
        sentence_id.append(word2id[word]);
    }
    return sentence_id;
}

